def adjust_values(dictionary, target_key):
    total_sum = sum(dictionary.values())
    b_index = dictionary.keys().index(target_key)

    desired_value_for_b = total_sum / 2
    difference = desired_value_for_b - dictionary[target_key]

    adjusted_values = {}
    for key, value in dictionary.items():
        if key == target_key:
            adjusted_values[key] = desired_value_for_b
        else:
            adjusted_values[key] = value + (difference * value / total_sum)

    return adjusted_values

