1. Install the Jira Script Runner plugin from the Atlassian Marketplace.
2. Create a new custom field of type "Checkbox" in your Jira project. Name it something like "All Checklist Items Done".
3. Open the script editor by navigating to `Admin` > `Scripts` > `Run Jira Script`.
4. Paste the following script into the editor:
```groovy
import com.atlassian.jira.ComponentManager;
import com.atlassian.jira.issue.Issue;
import com.atlassian.jira.issue.fields.CheckBoxField;
import com.atlassian.jira.issue.fields.CustomField;
import com.atlassian.jira.issue.fields.value.BooleanValue;
import com.atlassian.jira.issue.workflow.Workflow;
import com.atlassian.jira.issue.workflow.WorkflowTransition;
import com.atlassian.jira.util.I18nUtil;

def isAllChecklistItemsDone(issue) {
    def checkboxField = issue.getCustomField("All Checklist Items Done");
    def value = checkboxField.getValue();
    return value instanceof BooleanValue && value.booleanValue();
}

def blockTransitionIfChecklistNotDone(transition, issue) {
    if (!isAllChecklistItemsDone(issue)) {
        throw new RuntimeException(I18nUtil.getText("cannot.transition.issue", issue.getKey()));
    }
}

def preTransitions(transition, issue) {
    blockTransitionIfChecklistNotDone(transition, issue);
}
```
1. Save the script and associate it with the relevant workflow.
2. Go to the workflow configuration page for the workflow you want to modify.
3. Add a new transition or edit an existing one.
4. In the "Pre-transitions" section, select the "Jira Script" option and choose the script you just created.

