function reverseAdjectives(sentence) {
  const words = sentence.split(" ");
  const adjectives = [];

  for (let i = 0; i < words.length; i++) {
    if (words[i] === "beautiful" || words[i] === "green") {
      adjectives.push(words[i]);
    }
  }

  if (adjectives.length > 1) {
    const reversedAdjectives = adjectives.reverse();
    const newSentence = reversedAdjectives.join(" ") + " are in the park";
    return newSentence;
  } else {
    return sentence;
  }
}

