import javax.sound.sampled.AudioFileFormat;
import javax.sound.sampled.AudioInputStream;
import javax.sound.sampled.AudioSystem;
import java.io.File;
import java.io.IOException;

public class AudioCombiner {
    public static void main(String[] args) {
        File[] audioFiles = new File[] {
                new File("birds.wav"),
                new File("leaves.wav"),
                new File("cicadas.wav"),
                new File("children_playing.wav")
        };

        AudioInputStream[] inputStreams = new AudioInputStream[audioFiles.length];
        for (int i = 0; i < audioFiles.length; i++) {
            try {
                inputStreams[i] = AudioSystem.getAudioInputStream(audioFiles[i]);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        AudioInputStream outputStream = AudioSystem.getAudioInputStream(new File("output.wav"));
        AudioSystem.write(inputStreams, AudioFileFormat.WAV, outputStream);
    }
}
```

