public class SummerDay {
    public static void main(String[] args) throws IOException {
        File birdChirps = new File("bird_chirps.wav");
        File leafRustle = new File("leaf_rustle.wav");
        File cicadaHum = new File("cicada_hum.wav");
        File childPlayPool = new File("child_play_pool.wav");
        File picnicInPark = new File("picnic_in_park.wav");
        File lazyDayAtBeach = new File("lazy_day_at_beach.wav");

        Sox sox = new Sox();

        // Combine all audio files into one
        sox.addInput(birdChirps);
        sox.addInput(leafRustle);
        sox.addInput(cicadaHum);
        sox.addInput(childPlayPool);
        sox.addInput(picnicInPark);
        sox.addInput(lazyDayAtBeach);

        // Set output format and filename
        sox.setOutputFormat("wav");
        sox.setOutputFileName("summer_day.wav");

        // Mix and encode the audio
        sox.mix();
        sox.encode();

        // Clean up resources
        sox.close();
    }
}
```

