			const stringInput = document.querySelector('input[name="string"]').value;
			fetch('/extract-words', {
				method: 'POST',
				headers: {'Content-Type': 'application/json'},
				body: JSON.stringify({string: stringInput})
			}).then(response => response.text())
			.then(data => {
				document.getElementById('word-list').innerHTML = data;
			});
		});
	</script>
</body>
</html>
```

