    present_perfect = '^(\w+)\s+has\s+been\s+(\w+)$';
    past_perfect = '^(\w+)\s+had\s+been\s+(\w+)$';
    future_perfect = '^(\w+)\s+will\s+have\s+been\s+(\w+)$';

    % Use regular expressions to match the tense in the sentence
    matches = regexp(sentence, {present_simple, past_simple, future_simple, present_continuous, past_continuous, future_continuous, present_perfect, past_perfect, future_perfect}, 'match');

    % If a match is found, return the corresponding tense
    if ~isempty(matches)
        tense = matches{1};
    else
        tense = 'unknown';
    end
end

