```csharp
using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class RestServiceWrapper<T>
{
    private readonly string _baseUrl;
    private readonly string _authToken;

    public RestServiceWrapper(string baseUrl, string authToken)
    {
        _baseUrl = baseUrl;
        _authToken = authToken;
    }

    public async Task<T> GetAsync()
    {
        using (var client = new HttpClient())
        {
            client.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", _authToken);
            var response = await client.GetAsync(_baseUrl);
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsAsync<T>();
        }
    }
}

public class MyRestService
{
    private readonly RestServiceWrapper<MyModel> _restServiceWrapper;

    public MyRestService(string baseUrl, string authToken)
    {
        _restServiceWrapper = new RestServiceWrapper<MyModel>(baseUrl, authToken);
    }

    public async Task<MyModel> GetDataAsync()
    {
        return await _restServiceWrapper.GetAsync();
    }
}

public class MyModel
{
    public string Property1 { get; set; }
    public int Property2 { get; set; }
}
```

