Here's a simple example of a REST Service Wrapper Class in C# with authentication token handling:

```csharp
using System;
using System.Net.Http;
using System.Threading.Tasks;

public class RestServiceWrapper
{
    private readonly string _baseUrl;
    private readonly string _accessToken;

    public RestServiceWrapper(string baseUrl, string accessToken)
    {
        _baseUrl = baseUrl;
        _accessToken = accessToken;
    }

    public async Task<T> GetAsync<T>(string endpoint)
    {
        using (var client = new HttpClient())
        {
            client.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", _accessToken);

            var response = await client.GetAsync($"{_baseUrl}{endpoint}");
            response.EnsureSuccessStatusCode();

            return await response.Content.ReadAsAsync<T>();
        }
    }

    public async Task<T> PostAsync<T>(string endpoint, object data)
    {
        using (var client = new HttpClient())
        {
            client.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", _accessToken);

            var content = new StringContent(Newtonsoft.Json.JsonConvert.SerializeObject(data));
            content.Headers.ContentType = new MediaTypeHeaderValue("application/json");

            var response = await client.PostAsync($"{_baseUrl}{endpoint}", content);
            response.EnsureSuccessStatusCode();

            return await response.Content.ReadAsAsync<T>();
        }
    }
}
```

