Here's a simple Google Apps Script that searches for a place name in a column and stores its latitude and longitude in other columns. Make sure you have enabled Google Maps API in your Google Cloud Platform project.

```javascript
function searchPlace() {
  var sheet = SpreadsheetApp.getActiveSheet();
  var dataRange = sheet.getRange("A2:C"); // Assuming your data starts from cell A2
  var values = dataRange.getValues();

  for (var i = 0; i < values.length; i++) {
    var placeName = values[i][0]; // Assuming the first column contains place names
    var geocoder = new google.maps.Geocoder();

    geocoder.geocode({ 'address': placeName }, function(results, status) {
      if (status == google.maps.GeocoderStatus.OK) {
        var latitude = results[0].geometry.location.lat();
        var longitude = results[0].geometry.location.lng();

        sheet.getRange(i + 2, 2).setValue(latitude); // Assuming the second column will contain latitudes
        sheet.getRange(i + 2, 3).setValue(longitude); // Assuming the third column will contain longitudes
      } else {
        sheet.getRange(i + 2, 2).setValue(""); // Set an empty value if the geocoding fails
        sheet.getRange(i + 2, 3).setValue(""); // Set an empty value if the geocoding fails
      }
    });
  }
}
```

