4. Write the script to search for a place name and store the latitude and longitude:

```javascript
function searchPlace(placeName) {
  const apiKey = 'YOUR_API_KEY';
  const url = `https://maps.googleapis.com/maps/api/geocode/json?address=${placeName}&key=${apiKey}`;

  fetch(url)
    .then(response => response.json())
    .then(data => {
      const location = data.results[0].geometry.location;
      const latitude = location.lat;
      const longitude = location.lng;

      // Store the latitude and longitude in your spreadsheet
      // Replace 'Sheet1' with the name of your sheet and 'A1' with the cell where you want to store the latitude
      SpreadsheetApp.getActiveSpreadsheet().getSheetByName('Sheet1').getRange('A1').setValue(latitude);
      // Replace 'B1' with the cell where you want to store the longitude
      SpreadsheetApp.getActiveSpreadsheet().getSheetByName('Sheet1').getRange('B1').setValue(longitude);
    })
    .catch(error => console.error(error));
}
```

