```javascript
function smoothMap(x) {
  const smoothStart = 0.1;
  const smoothEnd = 0.9;
  const linearRange = 0.8;

  if (x <= smoothStart) {
    return x * x;
  } else if (x >= smoothEnd) {
    return 1 - (1 - x) * x;
  } else {
    return linearRange * x;
  }
}

// Test the function
