Here's a JavaScript function that takes a string variable in dot notation and returns all entries in an object where the nested key value matches the string key:

```javascript
function getNestedEntry(obj, key) {
  const keys = key.split(".");
  let currentObj = obj;

  for (const key of keys) {
    if (!currentObj.hasOwnProperty(key)) {
      return null;
    }
    currentObj = currentObj[key];
  }

  return currentObj;
}

// Example usage
const obj = {
  a: {
    b: {
      c: "value",
    },
  },
};

const key = "a.b.c";
const result = getNestedEntry(obj, key);
console.log(result); // Output: "value"
```

Here's a JavaScript function that takes a string variable in dot notation and returns all entries in an object where the nested key-value matches the string key:

```javascript
function getEntriesByKey(object, key) {
  const entries = [];

  for (const [k, v] of Object.entries(object)) {
    if (k === key) {
      entries.push(v);
    } else if (typeof v === 'object') {
      entries.push(...getEntriesByKey(v, key));
    }
  }

  return entries;
}
```

You can use this function like this:

```javascript
const obj = {
  a: 1,
  b: {
    c: 3,
    d: 4,
  },
  e: 5,
};

const key = 'c';
const entries = getEntriesByKey(obj, key);
console.log(entries); // Output: [3]
```

Here's a JavaScript function that takes a string variable in dot notation and returns all entries in an option where the nested key value matches the string key:

```javascript
function getEntryByKey(option, key) {
  const parts = key.split(".");
  let current = option;

  for (const part of parts) {
    if (!current[part]) {
      return null;
    }
    current = current[part];
  }

  return current;
}
```

You can use this function like this:

```javascript
const option = {
  name: "John",
  age: 30,
  city: "New York"
};

const key = "name";
const entry = getEntryByKey(option, key);
console.log(entry); // Output: John
```

