      <p>Current temperature: {temperature} {unit}</p>
      <button onClick={() => handleConvert('Fahrenheit')}>Convert to Fahrenheit</button>
      <button onClick={() => handleConvert('Celsius')}>Convert to Celsius</button>
    </div>
  );
};

export default TemperatureConverter;
```

Here's a simple React hook to convert temperatures between Celsius, Fahrenheit, and Kelvin:

```javascript
import { useState } from 'react';

const useTemperatureConverter = () => {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('celsius');

  const convertTemperature = (toUnit) => {
    if (unit === 'celsius') {
      switch (toUnit) {
        case 'fahrenheit':
          return (temperature * 9 / 5) + 32;
        case 'kelvin':
          return temperature + 273.15;
        default:
          return temperature;
      }
    } else if (unit === 'fahrenheit') {
      switch (toUnit) {
        case 'celsius':
          return (temperature - 32) * 5 / 9;
        case 'kelvin':
          return (temperature - 32) * 5 / 9 + 273.15;
        default:
          return temperature;
      }
    } else if (unit === 'kelvin') {
      switch (toUnit) {
        case 'celsius':
          return temperature - 273.15;
        case 'fahrenheit':
          return (temperature - 273.15) * 9 / 5 + 32;
        default:
          return temperature;
      }
    }
    return temperature;
  };

  return { temperature, unit, setTemperature, convertTemperature };
};

export default useTemperatureConverter;
```

