1. Create a new C# script called "AudioVisualizer" and attach it to your audio source object.
2. Add the following code to the "AudioVisualizer" script:
```csharp
using UnityEngine;

public class AudioVisualizer : MonoBehaviour
{
    public float waveHeight = 5f;
    public Color waveColor = Color.white;

    private AudioSource audioSource;
    private float sampleRate;
    private float[] samples;

    void Start()
    {
        audioSource = GetComponent<AudioSource>();
        sampleRate = audioSource.outputSampleRate;
        samples = new float[sampleRate];
    }

    void Update()
    {
        int samplesRead = audioSource.GetSamples(samples, 0, samples.Length);

        for (int i = 0; i < samplesRead; i++)
        {
            float amplitude = samples[i] / samples.Max();
            float wavePosition = i * sampleRate / audioSource.clip.length;

            Vector3 position = transform.position;
            position.y = waveHeight * amplitude * Mathf.Sin(wavePosition * Mathf.PI * 2);
            transform.position = position;
        }
    }
}
```
This script will create a wave visualizer that follows the audio signal. The wave height and color can be adjusted in the inspector.

To use this script, attach it to an audio source object in your scene, and adjust the properties in the inspector. The visualizer will be displayed in the scene view, following the audio signal.

