    prob_B = fitness_B / (fitness_A + fitness_B);

    % Generate offspring for each type
    N_A_offspring = floor(N_A * prob_A);
    N_B_offspring = floor(N_B * prob_B);

    % Update population sizes
    N_A = N_A - N_A_offspring;
    N_B = N_B - N_B_offspring;

    % Add newborns to the population
    N_A = N_A + N_A_offspring;
    N_B = N_B + N_B_offspring;

    % Increment generation counter
    generation = generation + 1;

    % Print out current generation information
    disp(['Generation ', num2str(generation), ':']);
    disp(['Type A: ', num2str(N_A), ' individuals']);
    disp(['Type B: ', num2str(N_B), ' individuals']);
end
```

