  scope: 'openid profile api1 api2', // Replace with the scopes needed for your app
});

export default auth0;
```
Replace `your-domain.com`, `your-client-id`, and `http://localhost:3000/callback` with your actual Auth0 domain, client ID, and redirect URI.

4. **Wrap your app in the Auth0 provider**: In your app's main component, wrap it in the Auth0 provider:
```javascript
// App.js
import React from 'react';
