Sure! Here's a Python script that uses `argparse` to read parameters, fetches all failed workflows, retrieves their inputs and names, and then re-executes them by using the same input as the original workflow and the same name but adding a "retry" suffix at the end:

```python
import argparse
import boto3

def get_failed_workflows(client):
    response = client.list_workflows()
    failed_workflows = []
    for workflow in response['workflows']:
        if workflow['status'] == 'Failed':
            failed_workflows.append(workflow)
    return failed_workflows

def retrieve_inputs_and_names(failed_workflows):
    inputs_and_names = {}
    for workflow in failed_workflows:
        inputs_and_names[workflow['name']] = workflow['input']
    return inputs_and_names

def re_execute_workflows(client, inputs_and_names):
    for name, input in inputs_and_names.items():
        retry_name = f"{name} retry"
        client.start_workflow(
            Name=retry_name,
            Input=input,
            Parameters={
                'retry': True
            }
        )

if __name__ == '__main__':
    parser = argparse.ArgumentParser(description='Retries failed Step Functions workflows')
    parser.add_argument('--region', required=True, help='AWS region')
    parser.add_argument('--workflow_name', required=True, help='Name of the Step Functions workflow')
    args = parser.parse_args()

    client = boto3.client('stepfunctions', region_name=args.region)
    failed_workflows = get_failed_workflows(client)
    inputs_and_names = retrieve_inputs_and_names(failed_workflows)
    re_execute_workflows(client, inputs_and_names)
```

