                               'Patient reported feeling tired and fatigued. Blood pressure and blood sugar levels were monitored.'];

% Save patient object to file
save('patient_data.mat', patient);

% Load patient object from file
load('patient_data.mat', patient);

% Display patient information
disp(['Name: ', patient.name]);
disp(['Age: ', num2str(patient.age)]);
disp(['Gender: ', patient.gender]);
disp(['Contact Info: ', patient.contact_info]);
disp(['Medical History: ', patient.medical_history]);
disp(['Consultation Notes: ', patient.consultation_notes]);
```

