Here's a Go code that identifies if a given sentence contains a double negative using a table of specific negative words:

```go
package main

import (
	"fmt"
	"strings"
)

var negativeWords = []string{"not", "never", "nothing", "no", "none"}

func isDoubleNegative(sentence string) bool {
	words := strings.Split(sentence, " ")
	for _, word := range words {
		if containsNegativeWord(word) && containsNotBeforeNegativeWord(word, sentence) {
			return true
		}
	}
	return false
}

func containsNegativeWord(word string) bool {
	for _, negWord := range negativeWords {
		if word == negWord || word == "-" + negWord {
			return true
		}
	}
	return false
}

func containsNotBeforeNegativeWord(word string, sentence string) bool {
	words := strings.Split(sentence, " ")
	prevWord := ""
	for i, w := range words {
		if w == "not" && prevWord != "" && containsNegativeWord(prevWord) {
			return true
		}
		prevWord = w
	}
	return false
}

