# Define the domain name
$domainName = "your_domain_name"

# Define the function to check if an SID is present in the SIDHistory of any user or group in the domain
function CheckSidInSIDHistory($sid) {
    $users = Get-ADUser -Filter {SID -eq $sid} -Properties SIDHistory
    $groups = Get-ADGroup -Filter {SID -eq $sid} -Properties SIDHistory

    if ($users.Count -gt 0) {
        return $true
    } elseif ($groups.Count -gt 0) {
        return $true
    } else {
        return $false
    }
}

# Define the function to recursively check folders for ACLs with SIDs in the SIDHistory
function CheckFolderACLs($folderPath) {
    $acl = (Get-Acl -Path $folderPath).Access

    foreach ($access in $acl) {
        if ($access.IdentityReference -match '^S-1-5-21-') {
            $sid = New-Object System.Security.Principal.SecurityIdentifier($access.IdentityReference)

            if (CheckSidInSIDHistory($sid)) {
                Write-Host "Folder '$folderPath' has an ACL with an SID in the SIDHistory."
            }
        }
    }

    foreach ($subFolder in (Get-ChildItem -Path $folderPath -Directory)) {
        CheckFolderACLs($subFolder.FullName)
    }
}

# Define the root folder to start the search from
$rootFolder = "C:\Path\To\Root\Folder"

# Check the ACLs of the root folder and its subfolders
CheckFolderACLs($rootFolder)
