# Define the function to check if an SID is in the SIDHistory of a user or group
function IsSIDInSIDHistory($sid) {
    $domain = (Get-ADDomain -Identity $_.Name).Name
    $searcher = New-Object System.DirectoryServices.DirectorySearcher($domain)
    $searcher.Filter = "(&(objectClass=user)(sAMAccountName=$username))"
    $searcher.PropertiesToLoad.Add("sIDHistory")
    $results = $searcher.FindAll()

    foreach ($result in $results) {
        if ($result.sIDHistory -contains $sid) {
            return $true
        }
    }

    return $false
}

